INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 11, 'theory', 'Quiz: networking, the stack and eBPF');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 0, 'Which route does the kernel choose if several table rows match?', '["The first in the table", "The last in the table", "The one with the lower interface number", "The one with the longest network prefix"]', 3, 'The default route 0.0.0.0/0 has a zero prefix and works as a fallback.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 1, 'What does the accept call return to the server?', '["The client''s address and nothing else", "A new descriptor for the connection with a particular client", "The same descriptor as listen", "The port chosen by the client"]', 1, 'The listening socket stays to accept new clients, and the exchange goes through the new descriptor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 2, 'How many addresses are there in total in a network with mask /24?', '["256", "24", "255", "65,536"]', 0, 'Usually 254 are available for hosts: one address is the network itself, another is the broadcast.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 3, 'What does XDP do?', '["Encrypts packets on the network card", "Rewrites the routing table", "Decides a packet''s fate in the driver, before sk_buff is created: pass, drop or redirect", "Compresses TCP headers"]', 2, 'It is the earliest point, so XDP is used for attack protection and load balancers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 4, 'Where to start diagnosing when "the network doesn''t work"?', '["By rebooting the router", "Go bottom up: link and address, route and gateway, name, port", "By reinstalling the program", "By checking the kernel version"]', 1, 'This shows on which floor the connection is lost: ip link, ip addr, ip route, resolvectl, ss.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 5, 'How does the kernel decide where to send a packet?', '["By the first matching entry in the table, in order", "It always sends to the default gateway", "It determines it by the host name via DNS", "By the routing table: the entry with the longest matching address prefix is chosen"]', 3, 'The longer the prefix, the more precise the route. The default gateway is an entry of zero length, the most general one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 6, 'Why is there a verifier when an eBPF program is loaded?', '["To make the program ten times faster", "To convert the program to machine code", "To prove that the program terminates and won''t touch foreign memory before it gets into the kernel", "To check the signature of the network card vendor"]', 2, 'The code runs inside the kernel, so safety is checked in advance: bounded loops, verified access bounds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 11, 7, 'Where to start diagnosing if the network doesn''t work?', '["Go bottom up: link and interface, address, route, names and only then the service", "Check DNS right away: the cause is almost always there", "Reboot the system", "First fix the firewall rules"]', 0, 'Each level depends on the one below. If there is no link on the interface, there is no point in studying routing.');
